import re

_OPERATORS = {
    "plus": lambda a, b: a + b,
    "minus": lambda a, b: a - b,
    "multiplied by": lambda a, b: a * b,
    "divided by": lambda a, b: a // b,
}

_NUMBER_RE = re.compile(r"-?\d+")


def _tokenize(text):
    """Split text into ("num", int), ("op", name) or ("word", word) tokens."""
    tokens = []
    words = text.split()
    i = 0
    while i < len(words):
        word = words[i]
        if word in ("multiplied", "divided") and i + 1 < len(words) and words[i + 1] == "by":
            tokens.append(("op", word + " by"))
            i += 2
        elif _NUMBER_RE.fullmatch(word):
            tokens.append(("num", int(word)))
            i += 1
        elif word in _OPERATORS:
            tokens.append(("op", word))
            i += 1
        else:
            tokens.append(("word", word))
            i += 1
    return tokens


def answer(question):
    question = question.strip()
    if not question.endswith("?"):
        raise ValueError("syntax error")

    tokens = _tokenize(question[:-1])
    if len(tokens) < 2 or tokens[0] != ("word", "What") or tokens[1] != ("word", "is"):
        raise ValueError("unknown operation")

    rest = tokens[2:]
    if not rest or rest[0][0] != "num":
        raise ValueError("syntax error")

    result = rest[0][1]
    i = 1
    while i < len(rest):
        token = rest[i]
        if token[0] == "word":
            raise ValueError("unknown operation")
        if token[0] != "op" or i + 1 >= len(rest) or rest[i + 1][0] != "num":
            raise ValueError("syntax error")
        result = _OPERATORS[token[1]](result, rest[i + 1][1])
        i += 2
    return result
